const fullscreenTrigger=document.createElement('button');fullscreenTrigger.id='pianoFullscreen';fullscreenTrigger.type='button';fullscreenTrigger.textContent='⛶';fullscreenTrigger.title='全屏演奏';fullscreenTrigger.setAttribute('aria-label','全屏演奏钢琴');$('.piano-toolbar').insertBefore(fullscreenTrigger,$('#pianoClose'));
const fullPiano=document.createElement('section');fullPiano.id='fullscreenPiano';fullPiano.hidden=true;fullPiano.setAttribute('role','dialog');fullPiano.setAttribute('aria-modal','true');fullPiano.setAttribute('aria-label','全屏钢琴演奏');fullPiano.innerHTML=`<header class="full-piano-header"><div><strong>和声花园</strong><small>全屏演奏</small></div><div class="full-piano-controls"><button id="fullOctDown" aria-label="整体降低八度">− 八度</button><span id="fullPianoRange"></span><button id="fullOctUp" aria-label="整体升高八度">＋ 八度</button><label>可视音区<select id="fullPianoOctaves"><option value="4">四八度</option><option value="3">三八度</option><option value="2">两八度</option><option value="1">一八度</option></select></label><label id="fullPianoBandLabel">位置<select id="fullPianoBand"><option value="-12">低音段</option><option value="0">中音段</option><option value="12">高音段</option></select></label><button id="fullStandToggle" aria-expanded="false">显示谱架</button><button id="fullPianoExit">退出全屏 ×</button></div></header><div id="fullScoreStand" hidden><label class="full-score-placeholder" for="fullScoreFile"><span>＋ 放一张自己的曲谱</span><small>图片仅在本机显示 · 可随时收起谱架</small></label><img id="fullScoreImage" alt="导入的曲谱" hidden><input id="fullScoreFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><div class="full-score-actions"><button id="fullScoreChange">更换谱图</button><button id="fullScoreClear">清空</button></div></div><div class="full-piano-stage"><div id="fullKeyboardSlot"></div><div class="full-piano-feedback"><span id="fullPianoStatus" role="status">按住琴键发声，松开释音。</span><small>数字 1–7 低音 · 字母键从中间 C 接续 · 支持多指同时弹奏</small></div></div>`;document.body.append(fullPiano);
const liveKeyboardHome=document.createComment('interactive keyboard home');$('#liveKeyboard').before(liveKeyboardHome);let pianoFullscreenOpen=false,fullScoreUrl=null,previousFocus=null;
const normalPianoKeys=pianoKeys;pianoKeys=function(){if(!pianoFullscreenOpen)return normalPianoKeys();const count=+$('#fullPianoOctaves').value,base=(octave+1)*12;let band=+$('#fullPianoBand').value;if(count===4)band=typeof pianoReferenceStart==='function'?pianoReferenceStart(base)-base:-18;else if(count===3)band=-12;if(count===2&&band===12)band=0;$('#fullPianoBand').value=String(band);$('#fullPianoBandLabel').hidden=count>=3;$('#fullPianoBand option[value="12"]').disabled=count===2;const start=base+band,end=start+count*12;$('#liveKeyboard').innerHTML=continuousKeyRow(start,end,base,true);$('#fullPianoRange').textContent=pianoNoteName(start)+' — '+pianoNoteName(end);$('#octLabel').textContent=pianoNoteName(base-18)+'–'+pianoNoteName(base+30);liveVisual()};
const baseLiveVisual=liveVisual;liveVisual=function(){baseLiveVisual();if(pianoFullscreenOpen)$('#fullPianoStatus').textContent=$('#liveStatus').textContent};
function restorePiano(){if(!pianoFullscreenOpen)return;releaseAll();pianoFullscreenOpen=false;liveKeyboardHome.after($('#liveKeyboard'));fullPiano.hidden=true;document.body.classList.remove('full-piano-open');pianoKeys();requestAnimationFrame(constrainDock);previousFocus?.focus()}
async function enterFullscreenPiano(){if(pianoFullscreenOpen)return;releaseAll();stopSong();previousFocus=document.activeElement;pianoFullscreenOpen=true;$('#fullPianoOctaves').value=innerWidth<650?'1':'4';$('#fullPianoBand').value=innerWidth<650?'0':'-12';$('#fullKeyboardSlot').append($('#liveKeyboard'));fullPiano.hidden=false;document.body.classList.add('full-piano-open');pianoKeys();try{if(fullPiano.requestFullscreen)await fullPiano.requestFullscreen()}catch{}$('#fullPianoExit').focus()}
async function leaveFullscreenPiano(){if(document.fullscreenElement===fullPiano){try{await document.exitFullscreen()}catch{}}restorePiano()}
fullscreenTrigger.onclick=enterFullscreenPiano;$('#fullPianoExit').onclick=leaveFullscreenPiano;document.addEventListener('fullscreenchange',()=>{if(pianoFullscreenOpen&&document.fullscreenElement!==fullPiano)restorePiano()});$('#fullOctDown').onclick=()=>changeOctave(-1);$('#fullOctUp').onclick=()=>changeOctave(1);['#fullPianoOctaves','#fullPianoBand'].forEach(s=>$(s).onchange=()=>{releaseAll();pianoKeys()});
$('#fullStandToggle').onclick=()=>{const stand=$('#fullScoreStand');stand.hidden=!stand.hidden;$('#fullStandToggle').textContent=stand.hidden?'显示谱架':'收起谱架';$('#fullStandToggle').setAttribute('aria-expanded',!stand.hidden)};
function clearScore(){if(fullScoreUrl)URL.revokeObjectURL(fullScoreUrl);fullScoreUrl=null;$('#fullScoreImage').hidden=true;$('#fullScoreImage').removeAttribute('src');$('.full-score-placeholder').hidden=false;$('#fullScoreFile').value=''}
$('#fullScoreChange').onclick=()=>$('#fullScoreFile').click();$('#fullScoreClear').onclick=clearScore;$('#fullScoreFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>15*1024*1024){$('#fullPianoStatus').textContent='请选择不超过 15MB 的 PNG、JPG 或 WebP 谱图';return}if(fullScoreUrl)URL.revokeObjectURL(fullScoreUrl);fullScoreUrl=URL.createObjectURL(f);$('#fullScoreImage').src=fullScoreUrl;$('#fullScoreImage').hidden=false;$('.full-score-placeholder').hidden=true};
document.addEventListener('keydown',e=>{if(!pianoFullscreenOpen)return;if(e.key==='Escape'&&!document.fullscreenElement){e.preventDefault();leaveFullscreenPiano()}if(e.key==='Tab'){const items=[...fullPiano.querySelectorAll('button,select,input:not([hidden])')].filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const handNote=document.createElement('p');handNote.className='hand-arrangement-note';handNote.textContent='左右手分工可变：弹唱常用左手低音、右手和弦或分解和弦；独奏常用左手伴奏、右手旋律。这里的亮键只表示实际发声音，不强制规定用哪只手。';$('.performance-legend').after(handNote);
